--- /dev/null
+++ b/src/domain/sales.js
@@ -0,0 +1,71 @@
+// Sales from the till: each line sells `qty` of a dish, which uses one recipe
+// portion per dish. Sales live in the ledger: a ticket's "consume" movements
+// carry the ref `sale:<ticket>` and the time of sale. A ticket is imported
+// once; a file of sales is all or nothing.
+import { AppError } from "../errors.js";
+import { dayOf } from "../dates.js";
+import { consume } from "./batches.js";
+import { getDish } from "./menu.js";
+import { getRecipe, scaled } from "./recipes.js";
+
+const REF = "sale:";
+
+/** True when a ticket was already imported (the ledger has its movements). */
+export function hasTicket(store, ticket) {
+  return store.data.movements.some((m) => m.ref === REF + ticket);
+}
+
+/**
+ * Records sale lines ({ row, ticket, soldAt, dishId, qty }) by consuming their
+ * ingredients at `soldAt` with the ref `sale:<ticket>`. Lines of tickets that
+ * were already imported are skipped. All or nothing: when an item runs out,
+ * nothing is kept and sale_out_of_stock names the row. Returns the counts of
+ * tickets and dishes recorded.
+ */
+export function recordSales(store, lines) {
+  const fresh = lines.filter((l) => !hasTicket(store, l.ticket));
+  const batchQty = new Map(store.data.batches.map((b) => [b, b.qty]));
+  const movements = store.data.movements.length;
+  const seq = { ...store.data.seq };
+  try {
+    for (const line of fresh) {
+      const recipe = getRecipe(store, getDish(store, line.dishId).recipeId);
+      for (const need of scaled(recipe, line.qty)) {
+        if (!(need.qty > 0)) continue;
+        try {
+          consume(store, need.itemId, need.qty, { at: line.soldAt, ref: REF + line.ticket });
+        } catch (e) {
+          if (e instanceof AppError && e.code === "not_enough_stock")
+            throw new AppError("sale_out_of_stock", { ...e.params, row: line.row, available: Math.round(e.params.available * 1000) / 1000 });
+          throw e;
+        }
+      }
+    }
+  } catch (e) {
+    for (const [batch, qty] of batchQty) batch.qty = qty;
+    store.data.movements.length = movements;
+    store.data.seq = seq;
+    throw e;
+  }
+  return {
+    tickets: new Set(fresh.map((l) => l.ticket)).size,
+    dishes: fresh.reduce((s, l) => s + l.qty, 0),
+  };
+}
+
+/**
+ * Theoretical use per item (Map of itemId to quantity) from sales sold between
+ * two days (inclusive): what the sales' recipes took, as booked on import.
+ */
+export function theoreticalUse(store, from, to) {
+  const batchItem = new Map(store.data.batches.map((b) => [b.id, b.itemId]));
+  const byItem = new Map();
+  for (const m of store.data.movements) {
+    if (m.type !== "consume" || !m.ref.startsWith(REF) || !batchItem.has(m.batchId)) continue;
+    const day = dayOf(m.at);
+    if (day < from || day > to) continue;
+    const itemId = batchItem.get(m.batchId);
+    byItem.set(itemId, (byItem.get(itemId) ?? 0) + m.qty);
+  }
+  return byItem;
+}
